op.execute("""
    REVOKE ALL ON FUNCTION public.apply_resource_offer(uuid,char(30),text,bigint) FROM PUBLIC,inv_app;
    CREATE FUNCTION public.apply_capability_offer(
        p_tenant uuid, p_capability char(30), p_actor char(30), p_offered bigint
    ) RETURNS TABLE(applied boolean, reason text, resource_ids text[], capacity bigint)
    LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $fn$
    DECLARE cap public.node_capabilities; node_id_value text; resource record;
      ids text[]; core_kind text; total_capacity numeric; total_leased numeric;
      remaining bigint; held bigint; next_offer bigint;
    BEGIN
      IF p_tenant IS DISTINCT FROM nullif(current_setting('inv.tenant_id',true),'')::uuid THEN
        RETURN QUERY SELECT false,'tenant_scope_mismatch',ARRAY[]::text[],NULL::bigint; RETURN;
      END IF;
      -- The trusted web service supplies its verified principal. Recheck it at
      -- the definer boundary; do not allow the old node/kind-only write path.
      PERFORM u.user_id FROM public.users u WHERE u.tenant_id=p_tenant AND u.user_id=p_actor
        AND u.status='active' FOR SHARE;
      IF NOT FOUND OR NOT public.business_admin_allowed(p_tenant,p_actor,'resources.manage') THEN
        RAISE EXCEPTION 'current resource administrator required' USING ERRCODE='42501';
      END IF;
      SELECT c.node_id INTO node_id_value FROM public.node_capabilities c
        WHERE c.tenant_id=p_tenant AND c.capability_id=p_capability;
      IF NOT FOUND THEN
        RETURN QUERY SELECT false,'capability_not_found',ARRAY[]::text[],NULL::bigint; RETURN;
      END IF;
      PERFORM n.node_id FROM public.nodes n WHERE n.tenant_id=p_tenant AND n.node_id=node_id_value FOR UPDATE;
      SELECT c.* INTO cap FROM public.node_capabilities c
        WHERE c.tenant_id=p_tenant AND c.capability_id=p_capability FOR UPDATE;
      IF p_offered IS NULL OR p_offered<0 OR p_offered>9007199254740991 OR p_offered>cap.total_quantity THEN
        RETURN QUERY SELECT false,'invalid_quantity',ARRAY[]::text[],NULL::bigint; RETURN;
      END IF;
      -- A GPU capability identifies a device; inv.resources has no device key.
      -- Recording intent is allowed, silently applying it to a different GPU is not.
      IF cap.kind='gpu' THEN
        RETURN QUERY SELECT false,'device_mapping_required',ARRAY[]::text[],NULL::bigint; RETURN;
      END IF;
      core_kind := CASE cap.kind WHEN 'cpu' THEN 'cpu' WHEN 'ram' THEN 'memory' WHEN 'disk' THEN 'storage' END;
      IF core_kind IS NULL OR cap.unit IS DISTINCT FROM (CASE cap.kind WHEN 'cpu' THEN 'millicores' ELSE 'bytes' END) THEN
        RETURN QUERY SELECT false,'unsupported_units',ARRAY[]::text[],NULL::bigint; RETURN;
      END IF;
      -- Same Node -> all sorted Resource locks used by reservation and offer writers.
      PERFORM n.node_id FROM inv.nodes n WHERE n.tenant_id=p_tenant AND n.node_id=node_id_value FOR UPDATE;
      IF NOT FOUND THEN
        RETURN QUERY SELECT false,'resource_not_registered',ARRAY[]::text[],NULL::bigint; RETURN;
      END IF;
      ids := ARRAY[]::text[];
      FOR resource IN SELECT r.resource_id FROM inv.resources r
        WHERE r.tenant_id=p_tenant AND r.node_id=node_id_value AND r.kind=core_kind
        ORDER BY r.resource_id FOR UPDATE LOOP
        ids := array_append(ids,resource.resource_id);
      END LOOP;
      IF cardinality(ids)=0 THEN
        RETURN QUERY SELECT false,'resource_not_registered',ids,NULL::bigint; RETURN;
      END IF;
      -- Separate statements after waiting: see the latest committed reservations,
      -- including expired/old-epoch leases without confirmed physical release.
      SELECT sum(r.capacity) INTO total_capacity FROM inv.resources r
        WHERE r.tenant_id=p_tenant AND r.resource_id=ANY(ids);
      SELECT coalesce(sum(l.amount),0) INTO total_leased FROM inv.resource_leases l
        WHERE l.tenant_id=p_tenant AND l.resource_id=ANY(ids) AND l.released_at IS NULL;
      IF p_offered>total_capacity THEN
        RETURN QUERY SELECT false,'exceeds_kernel_capacity',ids,least(total_capacity,9007199254740991)::bigint; RETURN;
      END IF;
      IF p_offered<total_leased THEN
        RETURN QUERY SELECT false,'below_unreleased_leases',ids,least(total_capacity,9007199254740991)::bigint; RETURN;
      END IF;
      IF EXISTS(SELECT 1 FROM inv.resources r WHERE r.tenant_id=p_tenant AND r.resource_id=ANY(ids)
        AND r.capacity < (SELECT coalesce(sum(l.amount),0) FROM inv.resource_leases l
          WHERE l.tenant_id=r.tenant_id AND l.resource_id=r.resource_id AND l.released_at IS NULL)) THEN
        RETURN QUERY SELECT false,'leased_capacity_inconsistent',ids,least(total_capacity,9007199254740991)::bigint; RETURN;
      END IF;
      remaining := p_offered-total_leased;
      FOR resource IN SELECT r.resource_id,r.capacity FROM inv.resources r
        WHERE r.tenant_id=p_tenant AND r.resource_id=ANY(ids) ORDER BY r.resource_id LOOP
        SELECT coalesce(sum(l.amount),0) INTO held FROM inv.resource_leases l
          WHERE l.tenant_id=p_tenant AND l.resource_id=resource.resource_id AND l.released_at IS NULL;
        next_offer := held+least(remaining,resource.capacity-held);
        UPDATE inv.resources r SET offered=next_offer
          WHERE r.tenant_id=p_tenant AND r.resource_id=resource.resource_id;
        remaining := remaining-(next_offer-held);
      END LOOP;
      RETURN QUERY SELECT true,NULL::text,ids,least(total_capacity,9007199254740991)::bigint;
    END $fn$;
    REVOKE ALL ON FUNCTION public.apply_capability_offer(uuid,char(30),char(30),bigint) FROM PUBLIC;
    GRANT EXECUTE ON FUNCTION public.apply_capability_offer(uuid,char(30),char(30),bigint) TO inv_app;
    """)

op.execute("""
    CREATE TABLE inv.credential_versions (
      tenant_id uuid NOT NULL, project_id text NOT NULL,
      credential_id uuid NOT NULL, version_id uuid NOT NULL,
      purpose text NOT NULL CHECK(purpose IN ('llm.invoke','git.read','git.publish','storage.read','storage.write','storage.gc','backup.write','backup.restore')),
      destination text NOT NULL CHECK(destination ~ '^[a-z][a-z0-9-]{0,63}$'),
      file_name text NOT NULL CHECK(file_name ~ '^[0-9a-f]{32}[.]secret$'),
      device bigint NOT NULL CHECK(device>=0), inode bigint NOT NULL CHECK(inode>0),
      content_sha256 text NOT NULL CHECK(content_sha256 ~ '^[0-9a-f]{64}$'),
      PRIMARY KEY(tenant_id,credential_id,version_id),
      UNIQUE(tenant_id,project_id,credential_id,version_id),
      FOREIGN KEY(tenant_id,project_id) REFERENCES inv.projects
    );
    CREATE TABLE inv.credential_grants (
      tenant_id uuid NOT NULL, project_id text NOT NULL,
      credential_id uuid NOT NULL, version_id uuid NOT NULL,
      subject_id text NOT NULL, run_id text NOT NULL,
      enabled boolean NOT NULL DEFAULT false, expires_at timestamptz NOT NULL,
      revoked_at timestamptz, recovery_epoch uuid NOT NULL,
      PRIMARY KEY(tenant_id,credential_id,version_id,subject_id,run_id),
      FOREIGN KEY(tenant_id,project_id,credential_id,version_id) REFERENCES inv.credential_versions(tenant_id,project_id,credential_id,version_id),
      FOREIGN KEY(tenant_id,project_id,run_id) REFERENCES inv.runs(tenant_id,project_id,run_id),
      FOREIGN KEY(tenant_id,project_id,subject_id) REFERENCES inv.project_grants
    );
    ALTER TABLE inv.credential_versions ENABLE ROW LEVEL SECURITY;
    ALTER TABLE inv.credential_versions FORCE ROW LEVEL SECURITY;
    ALTER TABLE inv.credential_grants ENABLE ROW LEVEL SECURITY;
    ALTER TABLE inv.credential_grants FORCE ROW LEVEL SECURITY;
    CREATE POLICY tenant_isolation ON inv.credential_versions
      USING(tenant_id=nullif(current_setting('inv.tenant_id',true),'')::uuid)
      WITH CHECK(tenant_id=nullif(current_setting('inv.tenant_id',true),'')::uuid);
    CREATE POLICY tenant_isolation ON inv.credential_grants
      USING(tenant_id=nullif(current_setting('inv.tenant_id',true),'')::uuid)
      WITH CHECK(tenant_id=nullif(current_setting('inv.tenant_id',true),'')::uuid);
    REVOKE ALL ON inv.credential_versions,inv.credential_grants FROM PUBLIC,inv_app,inv_kernel;
    GRANT SELECT ON inv.credential_versions,inv.credential_grants TO inv_kernel;
    CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON inv.credential_versions
      FOR EACH ROW EXECUTE FUNCTION inv.immutable_record();
    """)

op.execute("""
    CREATE TABLE inv.storage_sample_requests (
      tenant_id uuid NOT NULL, request_id uuid NOT NULL, project_id text NOT NULL,
      run_id text NOT NULL, subject_id text NOT NULL, contribution_id char(30) NOT NULL,
      run_version bigint NOT NULL, attempt integer NOT NULL, root_path text NOT NULL,
      sample_limit integer NOT NULL CHECK(sample_limit BETWEEN 1 AND 32),
      challenge jsonb NOT NULL, challenge_sha256 text NOT NULL CHECK(challenge_sha256 ~ '^[0-9a-f]{64}$'),
      created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
      PRIMARY KEY(tenant_id,request_id),
      FOREIGN KEY(tenant_id,project_id,run_id) REFERENCES inv.runs(tenant_id,project_id,run_id),
      FOREIGN KEY(tenant_id,contribution_id) REFERENCES public.storage_contributions(tenant_id,contribution_id),
      UNIQUE(tenant_id,challenge_sha256),
      CHECK(coalesce(challenge#>>'{channel,tenant_id}'=tenant_id::text AND challenge->>'run_id'=run_id
        AND challenge->>'project_id'=project_id AND challenge->>'contribution_id'=contribution_id::text,false))
    );
    CREATE UNIQUE INDEX storage_sample_nonce ON inv.storage_sample_requests(tenant_id,(challenge->>'nonce'));
    CREATE TABLE inv.storage_sample_consumptions (
      tenant_id uuid NOT NULL, request_id uuid NOT NULL,
      response_sha256 text NOT NULL CHECK(response_sha256 ~ '^[0-9a-f]{64}$'),
      evidence_id text NOT NULL, check_id char(30) NOT NULL,
      consumed_at timestamptz NOT NULL DEFAULT clock_timestamp(),
      PRIMARY KEY(tenant_id,request_id),
      FOREIGN KEY(tenant_id,request_id) REFERENCES inv.storage_sample_requests,
      FOREIGN KEY(tenant_id,evidence_id) REFERENCES inv.evidence,
      FOREIGN KEY(tenant_id,check_id) REFERENCES public.storage_checks(tenant_id,check_id),
      UNIQUE(tenant_id,evidence_id), UNIQUE(tenant_id,check_id)
    );
    DO $$ DECLARE tab text; BEGIN
      FOREACH tab IN ARRAY ARRAY['storage_sample_requests','storage_sample_consumptions'] LOOP
        EXECUTE format('ALTER TABLE inv.%I ENABLE ROW LEVEL SECURITY',tab);
        EXECUTE format('ALTER TABLE inv.%I FORCE ROW LEVEL SECURITY',tab);
        EXECUTE format('CREATE POLICY tenant_isolation ON inv.%I USING(tenant_id=nullif(current_setting(''inv.tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=nullif(current_setting(''inv.tenant_id'',true),'''')::uuid)',tab);
        EXECUTE format('REVOKE ALL ON inv.%I FROM PUBLIC,inv_app,inv_kernel',tab);
        EXECUTE format('GRANT SELECT,INSERT ON inv.%I TO inv_kernel',tab);
        EXECUTE format('CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON inv.%I FOR EACH ROW EXECUTE FUNCTION inv.immutable_record()',tab);
      END LOOP;
      FOREACH tab IN ARRAY ARRAY['nodes','storage_contributions','data_locations'] LOOP
        EXECUTE format('ALTER TABLE public.%I ADD COLUMN storage_lock_sentinel boolean NOT NULL DEFAULT true CHECK(storage_lock_sentinel)',tab);
        EXECUTE format('GRANT UPDATE(storage_lock_sentinel) ON public.%I TO inv_kernel',tab);
        EXECUTE format('CREATE POLICY storage_kernel_tenant ON public.%I TO inv_kernel USING(tenant_id=nullif(current_setting(''inv.tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=nullif(current_setting(''inv.tenant_id'',true),'''')::uuid)',tab);
      END LOOP;
    END $$;
    GRANT SELECT(tenant_id,node_id,status) ON public.nodes TO inv_kernel;
    GRANT SELECT(tenant_id,contribution_id,node_id,status,registered_by_user_id,normalized_path,version) ON public.storage_contributions TO inv_kernel;
    GRANT SELECT(tenant_id,contribution_id,location_id,version,relative_path,byte_size,checksum_sha256) ON public.data_locations TO inv_kernel;
    GRANT SELECT,INSERT ON public.storage_checks TO inv_kernel;
    CREATE POLICY storage_kernel_tenant ON public.storage_checks TO inv_kernel
      USING(tenant_id=nullif(current_setting('inv.tenant_id',true),'')::uuid)
      WITH CHECK(tenant_id=nullif(current_setting('inv.tenant_id',true),'')::uuid);
    CREATE TRIGGER immutable_signed_sample BEFORE UPDATE OR DELETE ON public.storage_checks
      FOR EACH ROW WHEN (OLD.detail->>'scope'='node-storage-sample-v1')
      EXECUTE FUNCTION inv.immutable_record();
    """)

op.execute("""
    CREATE TABLE inv.model_manifests (
      tenant_id uuid NOT NULL, project_id text NOT NULL, model_id text NOT NULL,
      version text NOT NULL, manifest jsonb NOT NULL CHECK(jsonb_typeof(manifest)='object'),
      manifest_sha256 text NOT NULL CHECK(manifest_sha256 ~ '^[0-9a-f]{64}$'),
      source_run_id text NOT NULL, recovery_epoch uuid NOT NULL,
      committed_at timestamptz NOT NULL DEFAULT clock_timestamp(),
      PRIMARY KEY(tenant_id,project_id,model_id,version),
      FOREIGN KEY(tenant_id,project_id,source_run_id) REFERENCES inv.runs(tenant_id,project_id,run_id),
      CHECK(coalesce(manifest->>'modelId'=model_id AND manifest->>'version'=version,false))
    );
    CREATE TABLE inv.model_shard_locations (
      tenant_id uuid NOT NULL, project_id text NOT NULL, model_id text NOT NULL,
      version text NOT NULL, shard_index integer NOT NULL CHECK(shard_index BETWEEN 0 AND 1023),
      location_id char(30) NOT NULL, location_version bigint NOT NULL CHECK(location_version>0),
      PRIMARY KEY(tenant_id,project_id,model_id,version,location_id),
      FOREIGN KEY(tenant_id,project_id,model_id,version) REFERENCES inv.model_manifests,
      FOREIGN KEY(tenant_id,location_id) REFERENCES public.data_locations(tenant_id,location_id)
    );
    DO $$ DECLARE tab text; BEGIN
      FOREACH tab IN ARRAY ARRAY['model_manifests','model_shard_locations'] LOOP
        EXECUTE format('ALTER TABLE inv.%I ENABLE ROW LEVEL SECURITY',tab);
        EXECUTE format('ALTER TABLE inv.%I FORCE ROW LEVEL SECURITY',tab);
        EXECUTE format('CREATE POLICY tenant_isolation ON inv.%I USING(tenant_id=nullif(current_setting(''inv.tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=nullif(current_setting(''inv.tenant_id'',true),'''')::uuid)',tab);
        EXECUTE format('REVOKE ALL ON inv.%I FROM PUBLIC,inv_app,inv_kernel',tab);
        EXECUTE format('GRANT SELECT,INSERT ON inv.%I TO inv_kernel',tab);
        EXECUTE format('CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON inv.%I FOR EACH ROW EXECUTE FUNCTION inv.immutable_record()',tab);
      END LOOP;
    END $$;
    """)

op.execute("""
    CREATE TABLE inv.model_run_inputs (
      tenant_id uuid NOT NULL, project_id text NOT NULL, run_id text NOT NULL,
      model_id text NOT NULL, model_version text NOT NULL,
      manifest_sha256 text NOT NULL CHECK(manifest_sha256 ~ '^[0-9a-f]{64}$'),
      node_id text NOT NULL, input jsonb NOT NULL CHECK(jsonb_typeof(input)='object'),
      PRIMARY KEY(tenant_id,run_id),
      FOREIGN KEY(tenant_id,project_id,run_id) REFERENCES inv.runs(tenant_id,project_id,run_id),
      FOREIGN KEY(tenant_id,project_id,model_id,model_version) REFERENCES inv.model_manifests,
      FOREIGN KEY(tenant_id,node_id) REFERENCES inv.nodes(tenant_id,node_id)
    );
    ALTER TABLE inv.model_run_inputs ENABLE ROW LEVEL SECURITY;
    ALTER TABLE inv.model_run_inputs FORCE ROW LEVEL SECURITY;
    CREATE POLICY tenant_isolation ON inv.model_run_inputs
      USING(tenant_id=nullif(current_setting('inv.tenant_id',true),'')::uuid)
      WITH CHECK(tenant_id=nullif(current_setting('inv.tenant_id',true),'')::uuid);
    REVOKE ALL ON inv.model_run_inputs FROM PUBLIC,inv_app,inv_kernel;
    GRANT SELECT,INSERT ON inv.model_run_inputs TO inv_kernel;
    CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON inv.model_run_inputs
      FOR EACH ROW EXECUTE FUNCTION inv.immutable_record();
    """)

op.execute("""
    CREATE TABLE inv.model_runtime_inputs (
      tenant_id uuid NOT NULL, project_id text NOT NULL, run_id text NOT NULL,
      input_id uuid NOT NULL, recovery_epoch uuid NOT NULL,
      requester_id text NOT NULL, workload jsonb NOT NULL,
      locations jsonb NOT NULL CHECK(jsonb_typeof(locations)='array' AND octet_length(locations::text)<=1048576),
      snapshot bytea NOT NULL CHECK(octet_length(snapshot) BETWEEN 1 AND 65536),
      PRIMARY KEY(tenant_id,run_id), UNIQUE(tenant_id,input_id),
      FOREIGN KEY(tenant_id,run_id) REFERENCES inv.model_run_inputs(tenant_id,run_id),
      FOREIGN KEY(tenant_id,project_id,run_id) REFERENCES inv.runs(tenant_id,project_id,run_id)
    );
    ALTER TABLE inv.model_runtime_inputs ENABLE ROW LEVEL SECURITY;
    ALTER TABLE inv.model_runtime_inputs FORCE ROW LEVEL SECURITY;
    CREATE POLICY tenant_isolation ON inv.model_runtime_inputs
      USING(tenant_id=nullif(current_setting('inv.tenant_id',true),'')::uuid)
      WITH CHECK(tenant_id=nullif(current_setting('inv.tenant_id',true),'')::uuid);
    REVOKE ALL ON inv.model_runtime_inputs FROM PUBLIC,inv_app,inv_kernel;
    GRANT SELECT,INSERT ON inv.model_runtime_inputs TO inv_kernel;
    CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON inv.model_runtime_inputs
      FOR EACH ROW EXECUTE FUNCTION inv.immutable_record();
    """)

op.execute("""
    CREATE TABLE inv.model_retry_lineage (
      tenant_id uuid NOT NULL, project_id text NOT NULL,
      root_run_id text NOT NULL, parent_run_id text NOT NULL, child_run_id text NOT NULL,
      generation integer NOT NULL CHECK(generation BETWEEN 2 AND 3),
      PRIMARY KEY(tenant_id,parent_run_id), UNIQUE(tenant_id,child_run_id),
      UNIQUE(tenant_id,root_run_id,generation),
      FOREIGN KEY(tenant_id,project_id,root_run_id) REFERENCES inv.runs(tenant_id,project_id,run_id),
      FOREIGN KEY(tenant_id,project_id,parent_run_id) REFERENCES inv.runs(tenant_id,project_id,run_id),
      FOREIGN KEY(tenant_id,project_id,child_run_id) REFERENCES inv.runs(tenant_id,project_id,run_id),
      CHECK(parent_run_id<>child_run_id AND root_run_id<>child_run_id)
    );
    ALTER TABLE inv.model_retry_lineage ENABLE ROW LEVEL SECURITY;
    ALTER TABLE inv.model_retry_lineage FORCE ROW LEVEL SECURITY;
    CREATE POLICY tenant_isolation ON inv.model_retry_lineage
      USING(tenant_id=nullif(current_setting('inv.tenant_id',true),'')::uuid)
      WITH CHECK(tenant_id=nullif(current_setting('inv.tenant_id',true),'')::uuid);
    REVOKE ALL ON inv.model_retry_lineage FROM PUBLIC,inv_app,inv_kernel;
    GRANT SELECT,INSERT ON inv.model_retry_lineage TO inv_kernel;
    CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON inv.model_retry_lineage
      FOR EACH ROW EXECUTE FUNCTION inv.immutable_record();
    """)

